    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students submit two sequences (a_n) of nonnegative integers and (b_n) of positive real numbers. Define x_n = a_n b_n for n = 1, 2, ..., {alpha}. Suppose the following three identities hold simultaneously:\n1) (sum_{n=1}^{alpha} x_n) * (sum_{k=0}^{n1-1} 1/((k+{p1})({q1}-k))) = sum_{k=1}^{n1} 1/(k(2k-1)).\n2) (sum_{k=1}^{n2} 1/(k(2k-1))) / (sum_{k=0}^{n2-1} 1/((k+{p2})({q2}-k))) = 1 + sum_{n=1}^{alpha} (x_n^2).\n3) (sum_{k=0}^{n3-1} 1/((k+{p3})({q3}-k))) * (2 * sum_{n=1}^{alpha} (x_n^3) - 1) = sum_{k=1}^{n3} 1/(k(2k-1)).\nFind the minimum possible value of sum_{n=1}^{alpha} (x_n^4). After solving, output your final answer in the following format:\n### The final answer is: \\boxed{<your answer>}\nYour answer should be exact (you may use fractions).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose n1 moderately large so alpha is large, ensuring non-trivial size
n1 = rng.randint(200, 1200)
alpha = 3 * n1 + 1  # ensures alpha ≡ 1 (mod 3)

# Derive n2 so that 1 + sum x_n^2 = alpha^2
n2 = (alpha * alpha - 1) // 3  # integer because alpha ≡ 1 (mod 3)

# Build (p_i, q_i) to make the telescoping ratios equal to p_i + q_i
p1, q1 = n1 + 1, 2 * n1
p2, q2 = n2 + 1, 2 * n2

# Choose n3 so that 2 * sum x_n^3 - 1 = 3*n3 + 1 = 2*alpha^3 - 3*alpha - 1
# i.e., sum x_n^3 = alpha^3 - (3/2) alpha
n3 = (2 * alpha**3 - 3 * alpha - 2) // 3
p3, q3 = n3 + 1, 2 * n3

# Return all placeholders
return {
    'alpha': alpha,
    'n1': n1, 'p1': p1, 'q1': q1,
    'n2': n2, 'p2': p2, 'q2': q2,
    'n3': n3, 'p3': p3, 'q3': q3
}

    def verifier(assign):
# Basic presence and type checks
try:
    alpha = int(assign['alpha'])
    n1 = int(assign['n1']); p1 = int(assign['p1']); q1 = int(assign['q1'])
    n2 = int(assign['n2']); p2 = int(assign['p2']); q2 = int(assign['q2'])
    n3 = int(assign['n3']); p3 = int(assign['p3']); q3 = int(assign['q3'])
except Exception:
    # Missing or non-integer placeholder
    return (False, None)

# Domain constraints for difficulty and validity
if alpha <= 0 or n1 <= 0 or n2 <= 0 or n3 <= 0:
    # invalid sizes
    return (False, None)
if alpha < 600:  # Ensure non-trivial scale to avoid easy guessing
    return (False, None)

# Structural constraints guaranteeing the telescoping identities used by the problem
if alpha % 3 != 1:
    return (False, None)
if not (p1 == n1 + 1 and q1 == 2 * n1):
    return (False, None)
if not (p2 == n2 + 1 and q2 == 2 * n2):
    return (False, None)
if not (p3 == n3 + 1 and q3 == 2 * n3):
    return (False, None)
if alpha != 3 * n1 + 1:
    return (False, None)
if 3 * n2 != alpha * alpha - 1:
    return (False, None)
if 3 * n3 != 2 * alpha**3 - 3 * alpha - 2:
    return (False, None)

# From the identities, we deduce deterministically:
# S1 = sum x_n = alpha
# S2 = sum x_n^2 = alpha^2 - 1
# S3 = sum x_n^3 = alpha^3 - (3/2) alpha
# By extremal/convexity arguments (see notes), the minimizing configuration has exactly two positive values x and y and others zero, with:
# x + y = S1 = alpha, and x^2 + y^2 = S2 = alpha^2 - 1 -> xy = (S1^2 - S2)/2 = 1/2.
# Then S4 = x^4 + y^4 = (x^2 + y^2)^2 - 2 (xy)^2 = (alpha^2 - 1)^2 - 1/2.

num = 2 * (alpha * alpha - 1)**2 - 1
answer = f"{num}/2"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

